// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IDexRouter} from "../interfaces/IDexRouter.sol";

interface IMintableERC20 is IERC20 {
    function mint(address to, uint256 amount) external;
}

/**
 * @title MockRouter
 * @notice Test double implementing the Uniswap V2-style {IDexRouter} interface.
 *         Pulls `amountIn` of `path[0]` from the caller and mints `amountIn *
 *         rateBps / 10_000` of `path[1]` back to `to`, simulating a swap at a
 *         configurable rate. Used to test {SableVault} deterministically until
 *         a real X Layer DEX router address is supplied.
 * @dev Assumes both tokens share the same decimals for simple rate math, which
 *      is sufficient for the vault's accounting tests.
 */
contract MockRouter is IDexRouter {
    /// @notice Output per input, in basis points (10_000 == 1:1).
    uint256 public rateBps = 10_000;

    function setRate(uint256 newRateBps) external {
        rateBps = newRateBps;
    }

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external override returns (uint256[] memory amounts) {
        require(deadline >= block.timestamp, "MockRouter: expired");
        require(path.length >= 2, "MockRouter: bad path");

        IMintableERC20(path[0]).transferFrom(msg.sender, address(this), amountIn);

        uint256 amountOut = (amountIn * rateBps) / 10_000;
        require(amountOut >= amountOutMin, "MockRouter: insufficient output");
        IMintableERC20(path[path.length - 1]).mint(to, amountOut);

        amounts = new uint256[](2);
        amounts[0] = amountIn;
        amounts[1] = amountOut;
    }
}

